new IteratorCodeTokenStream(
            (function () use ($stream) {
                while ($stream->isActive()) {
                    $token = $this->parseCodeToken($stream);

                    if ($token !== null) {
                        yield $token;
                    }
                }
            })(),
        )

new IteratorCodeTokenStream(
            (function () use ($stream, $file, $skip) {
                while ($stream->isActive()) {
                    yield $this->subParse($stream, $file);

                    if (count($skip) > 0) {
                        $stream->skip(...$skip);
                    }
                }
            })(),
        )

